import { Controller, Put, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const VISIBILITY_SCOPES = ['전체', '부서', '개인'];
const APPROVAL_VALUES = ['미사용', '사용'];

function isId(v: unknown): boolean {
  if (typeof v === 'number') {
    return Number.isInteger(v) && v > 0;
  }
  return typeof v === 'string' && /^\d+$/.test(v);
}

function fail(message: string): never {
  throw new ApiError(400, 'VALIDATION_FAILED', message);
}

@Controller('api/v1')
export class FnSfr03304Controller {
  @Put('/resources/:resourceId/settings')
  async updateResourceSettings(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자원 담당자');
    const data = checks.inputOf(req.body);
    const resourceId = req.params['resourceId'];
    if (!/^\d+$/.test(resourceId)) {
      fail('자원 ID 형식이 올바르지 않습니다.');
    }
    const permissionsIn = data['permissions'];
    if (!Array.isArray(permissionsIn)) {
      fail('사용 권한 대상 목록을 입력해 주세요.');
    }
    const attributesIn = data['attributes'] === undefined || data['attributes'] === null ? [] : data['attributes'];
    if (!Array.isArray(attributesIn)) {
      fail('자원 속성 목록 형식이 올바르지 않습니다.');
    }
    const approvalRequired = data['approvalRequired'];
    if (typeof approvalRequired !== 'string' || !APPROVAL_VALUES.includes(approvalRequired)) {
      fail('승인 절차 사용 여부는 미사용 또는 사용이어야 합니다.');
    }
    const visibilityScope = data['visibilityScope'];
    if (typeof visibilityScope !== 'string' || visibilityScope === '') {
      fail('공개범위를 입력해 주세요.');
    }
    if (!VISIBILITY_SCOPES.includes(visibilityScope as string)) {
      throw new ApiError(422, 'INVALID_VISIBILITY_SCOPE', '공개범위는 전체, 부서, 개인 중 하나여야 합니다.');
    }
    const approverRaw = data['approverEmployeeId'];
    const hasApprover = approverRaw !== undefined && approverRaw !== null && approverRaw !== '';
    if (hasApprover && !isId(approverRaw)) {
      fail('승인 담당자 형식이 올바르지 않습니다.');
    }
    if (approvalRequired === '사용' && !hasApprover) {
      throw new ApiError(422, 'APPROVER_REQUIRED', '승인 절차를 사용하려면 승인 담당자를 지정해 주세요.');
    }

    // 사용 범위(usageScope)의 값 체계는 확인 필요 항목이라 가정: 100자 이내 자유 입력으로 저장한다.
    const permissions: { employeeId: string | null; departmentId: string | null; usageScope: string | null }[] = [];
    const permissionKeys = new Set<string>();
    for (const raw of permissionsIn as unknown[]) {
      if (raw === null || typeof raw !== 'object' || Array.isArray(raw)) {
        fail('사용 권한 대상 형식이 올바르지 않습니다.');
      }
      const item = raw as Record<string, unknown>;
      const hasEmployee = item['employeeId'] !== undefined && item['employeeId'] !== null && item['employeeId'] !== '';
      const hasDepartment = item['departmentId'] !== undefined && item['departmentId'] !== null && item['departmentId'] !== '';
      if (hasEmployee === hasDepartment) {
        fail('사용 권한 대상은 임직원 또는 부서 중 하나만 지정해 주세요.');
      }
      const targetValue = hasEmployee ? item['employeeId'] : item['departmentId'];
      if (!isId(targetValue)) {
        fail('사용 권한 대상 ID 형식이 올바르지 않습니다.');
      }
      const scope = item['usageScope'];
      if (scope !== undefined && scope !== null && (typeof scope !== 'string' || scope.length > 100)) {
        fail('사용 범위는 100자 이내의 글자여야 합니다.');
      }
      const key = (hasEmployee ? 'E' : 'D') + String(targetValue);
      if (permissionKeys.has(key)) {
        fail('같은 사용 권한 대상이 중복되었습니다.');
      }
      permissionKeys.add(key);
      permissions.push({
        employeeId: hasEmployee ? String(targetValue) : null,
        departmentId: hasDepartment ? String(targetValue) : null,
        usageScope: typeof scope === 'string' && scope !== '' ? scope : null,
      });
    }

    const attributes: { name: string; value: string }[] = [];
    const attributeNames = new Set<string>();
    for (const raw of attributesIn as unknown[]) {
      if (raw === null || typeof raw !== 'object' || Array.isArray(raw)) {
        fail('자원 속성 형식이 올바르지 않습니다.');
      }
      const item = raw as Record<string, unknown>;
      const name = item['name'];
      const value = item['value'];
      if (typeof name !== 'string' || name.trim() === '' || name.length > 100) {
        fail('속성 항목명은 100자 이내로 입력해 주세요.');
      }
      if (typeof value !== 'string' || value.trim() === '' || value.length > 500) {
        fail('속성 값은 500자 이내로 입력해 주세요.');
      }
      if (attributeNames.has(name as string)) {
        fail('같은 속성 항목명이 중복되었습니다.');
      }
      attributeNames.add(name as string);
      attributes.push({ name: name as string, value: value as string });
    }

    return transaction(async (db) => {
      const found = await db.query(
        'SELECT resource_id FROM resource WHERE resource_id = CAST(:resourceId AS bigint)',
        { resourceId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'RESOURCE_NOT_FOUND', '설정할 자원을 찾을 수 없습니다.');
      }
      if (hasApprover) {
        const rows = await db.query(
          'SELECT employee_id FROM employee WHERE employee_id = CAST(:id AS bigint)',
          { id: String(approverRaw) },
        );
        if (rows.length === 0) {
          fail('승인 담당자로 지정한 임직원이 없습니다.');
        }
      }
      for (const p of permissions) {
        if (p.employeeId !== null) {
          const rows = await db.query(
            'SELECT employee_id FROM employee WHERE employee_id = CAST(:id AS bigint)',
            { id: p.employeeId },
          );
          if (rows.length === 0) {
            fail('사용 권한 대상 임직원이 없습니다.');
          }
        } else {
          const rows = await db.query(
            'SELECT department_id FROM department WHERE department_id = CAST(:id AS bigint)',
            { id: p.departmentId },
          );
          if (rows.length === 0) {
            fail('사용 권한 대상 부서가 없습니다.');
          }
        }
      }

      // 승인 절차 변경은 이후 신규 예약부터 적용된다. 기존 예약은 건드리지 않는다.
      await db.execute(
        'UPDATE resource SET approval_required = :approvalRequired, visibility_scope = :visibilityScope, updated_at = now() WHERE resource_id = CAST(:resourceId AS bigint)',
        { approvalRequired, visibilityScope, resourceId },
      );

      await db.execute(
        'DELETE FROM resource_permission WHERE resource_id = CAST(:resourceId AS bigint)',
        { resourceId },
      );
      for (const p of permissions) {
        await db.execute(
          'INSERT INTO resource_permission (resource_id, employee_id, department_id, usage_scope, created_at, updated_at) VALUES (CAST(:resourceId AS bigint), CAST(:employeeId AS bigint), CAST(:departmentId AS bigint), :usageScope, now(), now())',
          { resourceId, employeeId: p.employeeId, departmentId: p.departmentId, usageScope: p.usageScope },
        );
      }

      await db.execute(
        'DELETE FROM resource_attribute WHERE resource_id = CAST(:resourceId AS bigint)',
        { resourceId },
      );
      for (const a of attributes) {
        await db.execute(
          'INSERT INTO resource_attribute (resource_id, attribute_name, attribute_value, created_at, updated_at) VALUES (CAST(:resourceId AS bigint), :name, :value, now(), now())',
          { resourceId, name: a.name, value: a.value },
        );
      }

      await db.execute(
        'DELETE FROM resource_approver WHERE resource_id = CAST(:resourceId AS bigint)',
        { resourceId },
      );
      if (hasApprover) {
        await db.execute(
          'INSERT INTO resource_approver (resource_id, employee_id, created_at, updated_at) VALUES (CAST(:resourceId AS bigint), CAST(:employeeId AS bigint), now(), now())',
          { resourceId, employeeId: String(approverRaw) },
        );
      }

      const saved = await db.query(
        'SELECT resource_id AS "resourceId", approval_required AS "approvalRequired", visibility_scope AS "visibilityScope" FROM resource WHERE resource_id = CAST(:resourceId AS bigint)',
        { resourceId },
      );
      const savedPermissions = await db.query(
        'SELECT employee_id AS "employeeId", department_id AS "departmentId", usage_scope AS "usageScope" FROM resource_permission WHERE resource_id = CAST(:resourceId AS bigint) ORDER BY resource_permission_id',
        { resourceId },
      );
      const savedAttributes = await db.query(
        'SELECT attribute_name AS "name", attribute_value AS "value" FROM resource_attribute WHERE resource_id = CAST(:resourceId AS bigint) ORDER BY resource_attribute_id',
        { resourceId },
      );
      const savedApprover = await db.query(
        'SELECT employee_id AS "employeeId" FROM resource_approver WHERE resource_id = CAST(:resourceId AS bigint) ORDER BY resource_approver_id',
        { resourceId },
      );
      return {
        resourceId: saved[0]['resourceId'],
        permissions: savedPermissions,
        attributes: savedAttributes,
        approvalRequired: saved[0]['approvalRequired'],
        approverEmployeeId: savedApprover.length > 0 ? savedApprover[0]['employeeId'] : null,
        visibilityScope: saved[0]['visibilityScope'],
      };
    });
  }
}

