import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  Drawer,
  Field,
  Form,
  LookupSelect,
  Pairs,
  RefName,
  Select,
  TextInput,
  Tiles,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

interface PermissionDraft {
  kind: string;
  targetId: number | string;
  usageScope: string;
}

interface AttributeDraft {
  name: string;
  value: string;
}

export default function FnSfr03304Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [detail, setDetail] = useState<Row | null>(null);
  const [open, setOpen] = useState(false);
  const [resourceId, setResourceId] = useState<number | string>('');
  const [permissions, setPermissions] = useState<PermissionDraft[]>([]);
  const [attributes, setAttributes] = useState<AttributeDraft[]>([]);
  const [approvalRequired, setApprovalRequired] = useState('미사용');
  const [approverId, setApproverId] = useState<number | string>('');
  const [visibilityScope, setVisibilityScope] = useState('전체');

  const startSetting = () => {
    setResourceId('');
    setPermissions([]);
    setAttributes([]);
    setApprovalRequired('미사용');
    setApproverId('');
    setVisibilityScope('전체');
    setOpen(true);
  };

  const updatePermission = (index: number, patch: Partial<PermissionDraft>) => {
    setPermissions(permissions.map((p, i) => (i === index ? { ...p, ...patch } : p)));
  };

  const updateAttribute = (index: number, patch: Partial<AttributeDraft>) => {
    setAttributes(attributes.map((a, i) => (i === index ? { ...a, ...patch } : a)));
  };

  const submit = async () => {
    if (resourceId === '') {
      throw new Error('자원을 선택해 주세요.');
    }
    if (approvalRequired === '사용' && approverId === '') {
      throw new Error('승인 절차를 사용하려면 승인 담당자를 지정해 주세요.');
    }
    for (const p of permissions) {
      if (p.targetId === '') {
        throw new Error('사용 권한 대상을 선택해 주세요.');
      }
    }
    for (const a of attributes) {
      if (a.name.trim() === '' || a.value.trim() === '') {
        throw new Error('속성 항목명과 값을 모두 입력해 주세요.');
      }
    }
    const body: Row = {
      permissions: permissions.map((p) =>
        p.kind === 'employee'
          ? { employeeId: p.targetId, usageScope: p.usageScope }
          : { departmentId: p.targetId, usageScope: p.usageScope },
      ),
      attributes: attributes.map((a) => ({ name: a.name, value: a.value })),
      approvalRequired,
      visibilityScope,
    };
    if (approverId !== '') {
      body.approverEmployeeId = approverId;
    }
    const saved = await call('PUT', '/resources/' + String(resourceId) + '/settings', role, body);
    setResults([saved, ...results.filter((r) => r.resourceId !== saved.resourceId)]);
    setOpen(false);
    notify('자원 설정을 저장했습니다.');
  };

  const approvalCount = results.filter((r) => r.approvalRequired === '사용').length;

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>저장한 설정</h2>
        <Tiles items={[['건수', results.length]]} />
      </section>
      <section className="box span-4">
        <h2>승인 절차 사용</h2>
        <Tiles items={[['건수', approvalCount]]} />
      </section>
      <section className="box span-4">
        <h2>설정 시작</h2>
        <button type="button" onClick={startSetting}>자원 설정</button>
      </section>
      <section className="box span-12">
        <h2>설정 결과</h2>
        <Band total={results.length}>
          <button type="button" onClick={startSetting}>자원 설정</button>
        </Band>
        <DataTable
          rows={results}
          empty="이 화면에서 저장한 설정이 없습니다."
          onRowClick={(row) => setDetail(row)}
          columns={[
            { key: 'resourceId', label: '자원', render: (r) => <RefName table="resource" role={role} value={r.resourceId} /> },
            { key: 'approvalRequired', label: '승인 절차 사용 여부', render: (r) => <Badge value={r.approvalRequired} /> },
            { key: 'approverEmployeeId', label: '승인 담당자', render: (r) => <RefName table="employee" role={role} value={r.approverEmployeeId} /> },
            { key: 'visibilityScope', label: '공개범위', render: (r) => <Badge value={r.visibilityScope} /> },
          ]}
        />
      </section>
      {open && (
        <Drawer title="자원 사용 권한·승인 절차·공개범위 설정" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="저장">
            <Field label="자원 ID" required wide>
              <LookupSelect table="resource" role={role} value={resourceId} onChange={setResourceId} />
            </Field>
            <Field label="사용 권한 대상 목록" required wide hint="임직원 또는 부서 단위로 사용 범위를 지정합니다.">
              <div>
                {permissions.map((p, i) => (
                  <div key={i}>
                    <Select
                      value={p.kind}
                      onChange={(v) => updatePermission(i, { kind: v, targetId: '' })}
                      options={[['employee', '임직원'], ['department', '부서']]}
                    />
                    {p.kind === 'employee' ? (
                      <LookupSelect table="employee" role={role} value={p.targetId} onChange={(v) => updatePermission(i, { targetId: v })} />
                    ) : (
                      <LookupSelect table="department" role={role} value={p.targetId} onChange={(v) => updatePermission(i, { targetId: v })} />
                    )}
                    <TextInput value={p.usageScope} onChange={(v) => updatePermission(i, { usageScope: v })} placeholder="사용 범위" />
                    <button type="button" onClick={() => setPermissions(permissions.filter((_, j) => j !== i))}>삭제</button>
                  </div>
                ))}
                <button type="button" onClick={() => setPermissions([...permissions, { kind: 'employee', targetId: '', usageScope: '' }])}>
                  대상 추가
                </button>
              </div>
            </Field>
            <Field label="자원 속성 항목명과 값 목록" wide hint="예약 현황 조회의 검색 필터로 쓰입니다.">
              <div>
                {attributes.map((a, i) => (
                  <div key={i}>
                    <TextInput value={a.name} onChange={(v) => updateAttribute(i, { name: v })} placeholder="항목명" />
                    <TextInput value={a.value} onChange={(v) => updateAttribute(i, { value: v })} placeholder="값" />
                    <button type="button" onClick={() => setAttributes(attributes.filter((_, j) => j !== i))}>삭제</button>
                  </div>
                ))}
                <button type="button" onClick={() => setAttributes([...attributes, { name: '', value: '' }])}>
                  속성 추가
                </button>
              </div>
            </Field>
            <Field label="승인 절차 사용 여부" required>
              <Select
                value={approvalRequired}
                onChange={setApprovalRequired}
                options={[['미사용', '미사용'], ['사용', '사용']]}
              />
            </Field>
            <Field label="승인 담당자" required={approvalRequired === '사용'} hint="승인 절차를 사용하면 반드시 지정합니다.">
              <LookupSelect table="employee" role={role} value={approverId} onChange={setApproverId} />
            </Field>
            <Field label="공개범위" required>
              <Select
                value={visibilityScope}
                onChange={setVisibilityScope}
                options={[['전체', '전체'], ['부서', '부서'], ['개인', '개인']]}
              />
            </Field>
          </Form>
        </Drawer>
      )}
      {detail && (
        <Drawer title="자원 설정 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['자원 ID', <RefName table="resource" role={role} value={detail.resourceId} />],
              ['승인 절차 사용 여부', <Badge value={detail.approvalRequired} />],
              ['승인 담당자', <RefName table="employee" role={role} value={detail.approverEmployeeId} />],
              ['공개범위', <Badge value={detail.visibilityScope} />],
              [
                '저장된 사용 권한 목록',
                <div>
                  {((detail.permissions as Row[]) || []).map((p, i) => (
                    <div key={i}>
                      {p.employeeId ? <RefName table="employee" role={role} value={p.employeeId} /> : <RefName table="department" role={role} value={p.departmentId} />}
                      {' '}
                      {String(p.usageScope ?? '')}
                    </div>
                  ))}
                </div>,
              ],
              [
                '저장된 자원 속성 목록',
                <div>
                  {((detail.attributes as Row[]) || []).map((a, i) => (
                    <div key={i}>{String(a.name)}: {String(a.value)}</div>
                  ))}
                </div>,
              ],
            ]}
          />
        </Drawer>
      )}
    </div>
  );
}
